import{_ as e,o as r,c as t,a5 as s}from"./chunks/framework.BmD0ICqc.js";const m=JSON.parse('{"title":"WebGPUでシェーダーの出力を比べる","description":"","frontmatter":{"title":"WebGPUでシェーダーの出力を比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"shader-lab","order":1,"summary":"法線、GGX、露出、ノイズ、トゥーン、距離関数、水面のパラメーターを動かし、同じ座標で何が変わるかを見る。","aliases":["WebGPU","WGSL","シェーダー実践","シェーダーのパラメーター"]}},"headers":[],"relativePath":"practice/graphics/shader-lab.md","filePath":"practice/graphics/shader-lab.md"}'),h={name:"practice/graphics/shader-lab.md"};function d(l,a,i,o,n,p){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="webgpuでシェーダーの出力を比べる" tabindex="-1">WebGPUでシェーダーの出力を比べる <a class="header-anchor" href="#webgpuでシェーダーの出力を比べる" aria-label="Permalink to &quot;WebGPUでシェーダーの出力を比べる&quot;">​</a></h1><p>7つの題材を切り替え、スライダーを動かしたときに出力のどこが変わるかを観察します。JavaScriptは選択と数値をuniformバッファに書きます。WGSLのフラグメントシェーダーが画素ごとに色を計算し、WebGPUのキャンバスに表示します。WebGPUに対応したブラウザとGPUが必要です。</p><p><a href="/study/samples/graphics/shader-lab/index.html" target="_self">WebGPU実践を開く</a> · <a href="/study/samples/graphics/shader-lab/shader.wgsl" download>WGSLソース</a></p><h2 id="normals" tabindex="-1">法線と接空間 <a class="header-anchor" href="#normals" aria-label="Permalink to &quot;法線と接空間 {#normals}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=normals" target="_self">法線の実践を開く</a>。強さを0にして光の角度を変え、次に強さを上げます。球の外周と、球の内側の明暗を見比べます。接空間の入力は正弦波から生成しています。<a href="/study/graphics/shader/normal-mapping.html">法線マップと接空間</a></p><h2 id="brdf" tabindex="-1">GGXと材質 <a class="header-anchor" href="#brdf" aria-label="Permalink to &quot;GGXと材質 {#brdf}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=brdf" target="_self">GGXの実践を開く</a>。メタリックを0に保ち、粗さを0.2から0.7に上げます。次に粗さを固定し、メタリックを1にします。反射の広がりと、鏡面反射の色を別々に見ます。<a href="/study/graphics/shader/brdf-internals.html">BRDFの中身</a></p><h2 id="hdr" tabindex="-1">露出とトーンマッピング <a class="header-anchor" href="#hdr" aria-label="Permalink to &quot;露出とトーンマッピング {#hdr}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=hdr" target="_self">露出の実践を開く</a>。左右は同じリニアHDR値を使います。左は1でクリップし、右はチャンネルごとにReinhardの式 x / (1 + x) を適用します。+1 EVで変換前の値が2倍になります。発光の中心と周辺の色の差を比べます。<a href="/study/graphics/shader/color-space-and-hdr.html">色空間とHDR</a></p><h2 id="noise" tabindex="-1">fBmとドメインワープ <a class="header-anchor" href="#noise" aria-label="Permalink to &quot;fBmとドメインワープ {#noise}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=noise" target="_self">ノイズの実践を開く</a>。ワープ量を0にして左右が揃うことを確認します。オクターブを増やすと細かい模様が加わります。ワープ量を増やすと、右側でサンプリングする座標が変わります。<a href="/study/graphics/shader/procedural-noise.html">ノイズと手続き的テクスチャ</a></p><h2 id="toon" tabindex="-1">トゥーンとNPR <a class="header-anchor" href="#toon" aria-label="Permalink to &quot;トゥーンとNPR {#toon}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=toon" target="_self">トゥーンの実践を開く</a>。リムを0にし、段数を変えます。次に段数を固定してリムを増やし、光との角度で出る境界と、視線に対して浅い面に出る明るさを見比べます。<a href="/study/graphics/shader/toon-and-npr.html">トゥーンとNPR</a></p><h2 id="sdf" tabindex="-1">SDFとレイマーチング <a class="header-anchor" href="#sdf" aria-label="Permalink to &quot;SDFとレイマーチング {#sdf}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=sdf" target="_self">SDFの実践を開く</a>。合成幅を0から増やすと、2球が交わるところの輪郭が丸くつながります。影の硬さを動かすと、床で影から直射光に移る幅が変わります。影の式は近似です。<a href="/study/graphics/shader/sdf-and-raymarching.html">SDFとレイマーチング</a></p><h2 id="water" tabindex="-1">水面の反射と吸収 <a class="header-anchor" href="#water" aria-label="Permalink to &quot;水面の反射と吸収 {#water}&quot;">​</a></h2><p><a href="/study/samples/graphics/shader-lab/index.html?mode=water" target="_self">水面の実践を開く</a>。波の強さを0にして吸収を動かすと、水が深い右側から海底の模様が薄くなります。次に波を強め、反射の明るい部分と海底の模様が動く方向を見ます。空と海底はシェーダー内で生成しています。<a href="/study/graphics/shader/water-shading.html">水面の表現</a></p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/learn/roadmap.html#shaders">シェーダーのロードマップ</a></li><li><a href="/study/graphics/shader/wgsl.html">WGSL</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://www.w3.org/TR/2026/CRD-webgpu-20260915/" target="_blank" rel="noreferrer">W3C WebGPU Candidate Recommendation Draft、2026年9月15日</a></li><li><a href="https://www.w3.org/TR/2026/CRD-WGSL-20261106/" target="_blank" rel="noreferrer">W3C WebGPU Shading Language Candidate Recommendation Draft、2026年11月6日</a></li><li><a href="https://www-old.cs.utah.edu/docs/techreports/2002/pdf/UUCS-02-001.pdf" target="_blank" rel="noreferrer">Reinhardほか、Photographic Tone Reproduction for Digital Images、SIGGRAPH 2002</a></li></ul>',21)])])}const f=e(h,[["render",d]]);export{m as __pageData,f as default};
